import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BvnCBqQl.js";const g=JSON.parse('{"title":"Lab 4：mini-dify v0.4 —— 工具、Agent、MCP","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/lab-4-agent-tools-mcp.md","filePath":"chapters/lab-4-agent-tools-mcp.md","lastUpdated":1791442702000}'),i={name:"chapters/lab-4-agent-tools-mcp.md"};function s(l,t,n,p,r,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="lab-4-mini-dify-v0-4-——-工具、agent、mcp" tabindex="-1">Lab 4：mini-dify v0.4 —— 工具、Agent、MCP <a class="header-anchor" href="#lab-4-mini-dify-v0-4-——-工具、agent、mcp" aria-label="Permalink to &quot;Lab 4：mini-dify v0.4 —— 工具、Agent、MCP&quot;">​</a></h1><blockquote><p>目标：内置工具 + OpenAPI 自定义工具 + 工作流即工具 + MCP 工具；Function Calling 和 ReAct 两种 Agent；聊天 Playground 支持 Agent 模式；工作流中的 Agent 节点和工具节点；MCP 客户端和 MCP Server。 起点 <code>v0.3</code>，终点 <code>v0.4</code>。</p></blockquote><h2 id="构建顺序" tabindex="-1">构建顺序 <a class="header-anchor" href="#构建顺序" aria-label="Permalink to &quot;构建顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>文件</th><th>章节</th></tr></thead><tbody><tr><td>1</td><td><code>app/llm/mock.py</code>：学会“调用工具”和 ReAct；顺带加入哈希向量（v0.5 要用）</td><td>18</td></tr><tr><td>2</td><td><code>app/tools/base.py</code>、<code>builtin.py</code>（时间、计算器、网页抓取）</td><td>19</td></tr><tr><td>3</td><td><code>app/tools/api_tool.py</code>（OpenAPI 解析）</td><td>19</td></tr><tr><td>4</td><td><code>app/mcp/client.py</code>（stdio + HTTP）→ <code>app/tools/mcp_tool.py</code></td><td>20</td></tr><tr><td>5</td><td><code>app/tools/workflow_tool.py</code>、<code>manager.py</code></td><td>19</td></tr><tr><td>6</td><td><code>app/agent/prompts.py</code>、<code>runner.py</code>（两种 Runner）</td><td>18</td></tr><tr><td>7</td><td><code>app/workflow/nodes/agent.py</code>（Agent 节点、工具节点）+ <code>NodeRunAgentLog</code> 事件 + 转换器支持 <code>agent_log</code></td><td>21</td></tr><tr><td>8</td><td><code>app/api/chat.py</code> 的 Agent 模式（<code>agent_thought</code> / <code>agent_message</code> 事件）</td><td>18</td></tr><tr><td>9</td><td><code>app/api/tools.py</code>、<code>app/mcp/server.py</code>、<code>models.py</code> 新增 <code>ToolProviderRecord</code></td><td>19、20</td></tr><tr><td>10</td><td><code>examples/mcp_demo_server.py</code></td><td>20</td></tr><tr><td>11</td><td>前端：<code>lib/useTools.ts</code>、<code>components/ToolPicker.tsx</code>、<code>pages/ToolsPage.tsx</code>、ChatPage 的 Agent 模式、Agent/工具两种节点的面板</td><td>19、21</td></tr></tbody></table><h2 id="演示脚本" tabindex="-1">演示脚本 <a class="header-anchor" href="#演示脚本" aria-label="Permalink to &quot;演示脚本&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-dify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.4</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动后端和前端</span></span></code></pre></div><ol><li><strong>工具页</strong> → “＋ MCP Server” → stdio：<code>python3</code> + <code>../examples/mcp_demo_server.py</code> → 保存。点击 <code>get_weather</code>，输入“北京”，返回 <code>北京：晴 26°C</code>；</li><li><strong>聊天 Playground</strong> → 勾选“计算器”和“get_weather” → 问“帮我算 (12+8)*3”，再问“查一下 get_weather 上海”。每条回答上方会显示 🔧 工具调用和 👀 观察结果；</li><li>把策略切换成 ReAct，再问一次，回答相同，但思考过程是文字形式的；</li><li><strong>工作流</strong>：开始 → Agent（勾选计算器，问题写“请计算 99*99”）→ 结束 → 运行。在追踪里展开 Agent 节点，查看 steps；</li><li><strong>工作流即工具</strong>：发布一个 Workflow 应用，它会出现在工具页的 workflow 分组里，可以被另一个应用的 Agent 调用；</li><li><strong>MCP Server</strong>：<code>curl -X POST localhost:5001/mcp/&lt;app_id&gt; -H &#39;Content-Type: application/json&#39; -d &#39;{&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;method&quot;:&quot;tools/list&quot;}&#39;</code>（v0.4 没有鉴权；v1.0 需要加上 <code>Authorization: Bearer &lt;API Key&gt;</code>）。</li></ol><h2 id="换成真实模型" tabindex="-1">换成真实模型 <a class="header-anchor" href="#换成真实模型" aria-label="Permalink to &quot;换成真实模型&quot;">​</a></h2><p>v0.4 还没有工作空间凭证设置（v1.0 才加），所以通过环境变量配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENAI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:11434/v1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ollama</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvicorn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.main:app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5001</span></span></code></pre></div><p>然后在聊天 Playground 的模型框中填 <code>openai/qwen2.5:7b</code>（Ollama 上的小模型基本都支持工具调用，0.5B 的版本也能用，第 18 章有实测记录）。</p><h2 id="验收清单" tabindex="-1">验收清单 <a class="header-anchor" href="#验收清单" aria-label="Permalink to &quot;验收清单&quot;">​</a></h2><ul><li>[ ] <code>uv run pytest -q</code>：28 个测试通过（v0.4 的数量）</li><li>[ ] 两种 Agent 策略都能正确完成计算器任务</li><li>[ ] OpenAPI 工具在接口不可达时返回错误结果，而不是 500</li><li>[ ] stdio 方式的 MCP Server 能添加，也能调用</li><li>[ ] 工作流中 Agent 节点的追踪包含 steps；Answer 节点能流式输出 Agent 的回答</li><li>[ ] 已发布的工作流可以作为工具被调用，也可以通过 MCP 协议被调用</li></ul><h2 id="写作时踩到的坑-真实记录" tabindex="-1">写作时踩到的坑（真实记录） <a class="header-anchor" href="#写作时踩到的坑-真实记录" aria-label="Permalink to &quot;写作时踩到的坑（真实记录）&quot;">​</a></h2><ol><li><strong>计算器精度</strong>：<code>:g</code> 格式把 7006652 变成了 <code>7.00665e+06</code>，模型又把它“还原”成了错误的 7,006,650。改为整数原样输出（第 18 章）。</li><li><strong>ReAct 示例里的嵌套代码块</strong>：写书时，Markdown 代码块里又包含了 ```，导致渲染错乱。外层改用 <code>~~~~</code> 就好了。这和 ReAct 本身无关，但如果你要在文档里展示 ReAct 提示词，迟早会遇到。</li><li><strong>v1.0 才补上的两个安全问题</strong>（写第 19、20 章时对照 Dify 发现的）：工作流即工具没有调用深度限制，可能无限递归；stdio MCP 在多租户场景下等于允许用户在服务器上执行任意命令。这两个问题都在 v1.0 里修复了，并加了回归测试。<strong>如果你基于 v0.4 做实验，要清楚这两个风险。</strong></li></ol>',15)])])}const k=e(i,[["render",s]]);export{g as __pageData,k as default};
